-- Generated by scripts/current-sql.mjs; documentation only.
-- Signature: app.review_comments(p_submission_id uuid)
-- Owner: cms_migration_owner
-- ACL: {cms_migration_owner=X/cms_migration_owner,cms_authenticated_user=X/cms_migration_owner}

CREATE OR REPLACE FUNCTION app.review_comments(p_submission_id uuid)
 RETURNS TABLE(id uuid, body text, mentions jsonb, author_id uuid, author_name text, created_at timestamp with time zone, resolved_at timestamp with time zone, resolved_by uuid, resolved_by_name text, can_resolve boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE actor uuid; request RECORD;
BEGIN
  actor := app.require_actor();
  SELECT s.id, s.site_id, s.item_id, s.version_id, s.submitted_by
    INTO request
    FROM public.submissions s
   WHERE s.id = p_submission_id
     AND s.item_type = 'page'
     AND app.has_page_access(s.item_id)
     AND (s.submitted_by = actor OR app.can_publish_page(s.item_id));
  IF request IS NULL THEN
    RAISE EXCEPTION 'no such submission' USING ERRCODE = 'CMS03';
  END IF;

  RETURN QUERY
  SELECT c.id, c.body, c.mentions, c.author_id,
         COALESCE(NULLIF(author.display_name, ''), author.email),
         c.created_at, c.resolved_at, c.resolved_by,
         COALESCE(NULLIF(resolver.display_name, ''), resolver.email),
         (c.author_id = actor OR app.can_publish_page(request.item_id))
    FROM public.comments c
    JOIN public.app_users author ON author.id = c.author_id
    LEFT JOIN public.app_users resolver ON resolver.id = c.resolved_by
   WHERE c.site_id = request.site_id
     AND c.item_type = 'page'
     AND c.item_id = request.item_id
     AND c.version_id = request.version_id
   ORDER BY c.created_at;
END
$function$
